<?php
require_once __DIR__.'/../includes/user-check.php';$q=$pdo->prepare('SELECT d.id,d.hasil,d.created_at,m.kode motor_kode,m.nama motor_nama,m.merek,m.tahun,k.kode kerusakan_kode,k.nama kerusakan_nama FROM diagnosis d JOIN motor m ON m.id=d.motor_id LEFT JOIN kerusakan k ON k.id=d.kerusakan_id WHERE d.user_id=? ORDER BY d.created_at DESC,d.id DESC');$q->execute([(int)$_SESSION['user']['id']]);$rows=$q->fetchAll();$page_title='Riwayat Diagnosis';require __DIR__.'/../includes/header.php';
?><section class="app-content-header"><div class="container-fluid"><h3>Riwayat Diagnosis</h3><p class="text-body-secondary">Daftar diagnosis yang pernah Anda lakukan.</p></div></section><section class="content"><div class="container-fluid"><div class="card"><div class="card-header"><h3 class="card-title">Riwayat Saya (<?= count($rows) ?>)</h3><a class="btn btn-primary btn-sm float-end" href="diagnosis.php">Diagnosis Baru</a></div><div class="card-body"><div class="table-responsive"><table class="table table-bordered table-hover align-middle"><thead><tr><th>No</th><th>Tanggal</th><th>Motor</th><th>Hasil</th><th>Aksi</th></tr></thead><tbody><?php if($rows):foreach($rows as $i=>$r): ?><tr><td><?= $i+1 ?></td><td><?= e(date('d-m-Y H:i',strtotime($r['created_at']))) ?></td><td><?= e($r['motor_kode'].' - '.$r['merek'].' '.$r['motor_nama'].($r['tahun']?' '.$r['tahun']:'')) ?></td><td><?php if($r['kerusakan_kode']): ?><span class="badge text-bg-success"><?= e($r['kerusakan_kode'].' - '.$r['kerusakan_nama']) ?></span><?php else: ?><span class="badge text-bg-warning"><?= e($r['hasil']) ?></span><?php endif ?></td><td><a class="btn btn-info btn-sm" href="detail-riwayat.php?id=<?= (int)$r['id'] ?>">Detail</a></td></tr><?php endforeach;else: ?><tr><td colspan="5" class="text-center py-4">Belum ada riwayat diagnosis.</td></tr><?php endif ?></tbody></table></div></div></div></div></section><?php require __DIR__.'/../includes/footer.php'; ?>
